create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','manager','staff','cleaner','inspector','maintenance');
create type public.room_state as enum ('ready','reserved','occupied','cleaning','inspection','maintenance','needs_attention','exclusive','staff','utility');
create table public.properties(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'Europe/Tallinn',created_at timestamptz not null default now());
create table public.memberships(property_id uuid references public.properties on delete cascade,user_id uuid references auth.users on delete cascade,role public.app_role not null,primary key(property_id,user_id));
create table public.rooms(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties on delete cascade,name text not null,kind text not null default 'guest',state public.room_state not null default 'ready',map_shape jsonb not null default '{}',door_ids text[] not null default '{}',unique(property_id,name));
create table public.guests(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties on delete cascade,email text,name text not null,phone text,license_plates text[] not null default '{}',created_at timestamptz not null default now());
create table public.bookings(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties on delete cascade,guest_id uuid not null references public.guests on delete restrict,start_at timestamptz not null,end_at timestamptz not null,status text not null default 'reserved',delivery_channels text[] not null default '{qr}',check(end_at>start_at));
create table public.booking_rooms(booking_id uuid references public.bookings on delete cascade,room_id uuid references public.rooms on delete restrict,primary key(booking_id,room_id));
create table public.credentials(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings on delete cascade,type text not null check(type in('qr','pin','license_plate','card')),external_id text,value_ciphertext text,status text not null default 'pending',valid_from timestamptz not null,valid_until timestamptz not null,check(valid_until>valid_from));
create table public.task_groups(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties on delete cascade,name text not null,role public.app_role not null,sequence int not null default 0);
create table public.tasks(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties on delete cascade,room_id uuid references public.rooms on delete cascade,group_id uuid references public.task_groups on delete set null,title text not null,status text not null default 'open',recurrence jsonb,hidden_until timestamptz,attention_note text,completed_by uuid references auth.users,completed_at timestamptz,created_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,property_id uuid not null references public.properties on delete cascade,actor_id uuid references auth.users,action text not null,target_type text not null,target_id text,reason text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table public.properties enable row level security;alter table public.memberships enable row level security;alter table public.rooms enable row level security;alter table public.guests enable row level security;alter table public.bookings enable row level security;alter table public.booking_rooms enable row level security;alter table public.credentials enable row level security;alter table public.task_groups enable row level security;alter table public.tasks enable row level security;alter table public.audit_log enable row level security;
create function public.is_property_member(p uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.memberships m where m.property_id=p and m.user_id=(select auth.uid()))$$;
create function public.is_property_manager(p uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.memberships m where m.property_id=p and m.user_id=(select auth.uid()) and m.role in('owner','manager'))$$;
create policy property_read on public.properties for select to authenticated using(public.is_property_member(id));
create policy membership_read on public.memberships for select to authenticated using(user_id=(select auth.uid()) or public.is_property_manager(property_id));
create policy room_read on public.rooms for select to authenticated using(public.is_property_member(property_id));create policy room_manage on public.rooms for all to authenticated using(public.is_property_manager(property_id)) with check(public.is_property_manager(property_id));
create policy guest_manage on public.guests for all to authenticated using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy booking_manage on public.bookings for all to authenticated using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy task_read on public.tasks for select to authenticated using(public.is_property_member(property_id));create policy task_update on public.tasks for update to authenticated using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy group_read on public.task_groups for select to authenticated using(public.is_property_member(property_id));
create policy audit_read on public.audit_log for select to authenticated using(public.is_property_manager(property_id));
revoke all on public.credentials from anon,authenticated;revoke all on public.audit_log from anon;grant select,insert,update,delete on public.properties,public.memberships,public.rooms,public.guests,public.bookings,public.booking_rooms,public.task_groups,public.tasks to authenticated;grant select on public.audit_log to authenticated;
